ze",i==0?.7f:i==7?3:8);m.SetFloat("_SlabSize",slabs[i]);m.SetFloat("_JointStrength",i==0?0:i==7?.23f:i==1?.16f:.15f);m.SetFloat("_DustStrength",.018f);m.SetFloat("_Contrast",i==0?.95f:.5f);m.SetFloat("_Brightness",1.13f);AssetDatabase.CreateAsset(m,folder+"/"+names[i]+".mat");mats[i]=m;}
