var white=RoadMat(folder,"CargoBayWhite",new Color(.83f,.86f,.82f));var paint=new List<CombineInstance>();foreach(float z in new[]{-480f,-200,70,250,420,560}){foreach(var rect in new[]{new Vector4(194,z-20,235,z-19.8f),new Vector4(194,z+19.8f,235,z+20),new Vector4(194,z-20,194.2f,z+20),new Vector4(234.8f,z-20,235,z+20)}){var p=GameObject.CreatePrimitive(PrimitiveType.Cube);p.transform.position=new Vector3((rect.x+rect.z)/2,.031f,(rect.y+rect.w)/2);p.transform.localScale=new Vector3(rect.z-rect.x,.002f,rect.w-rect.y);paint.Add(new CombineInstance{mesh=p.GetComponent<MeshFilter>().sharedMesh,transform=p.transform.localToWorldMatrix});Object.DestroyImmediate(p);}}var pm=new Mesh{name="QuayCargoBayPaint"};pm.CombineMeshes(paint.ToArray());AssetDatabase.CreateAsset(pm,folder+"/QuayCargoBayPaint.asset");var pg=new GameObject("Six_CargoBay_Outlines");pg.transform.SetParent(root.transform);pg.AddComponent<MeshFilter>().sharedMesh=pm;pg.AddComponent<MeshRenderer>().sharedMaterial=white;
